        "page": 2,
        "text": "KIRISH F i z i k a deb, tabiat hodisalarini, modda va maydon xossalari va ularning sabab va qonuniyatlarini o‘rganuvchi fanga aytiladi. Fizika yunoncha “phusis” - tabiat degan so‘zdan olingan bo‘lib, tabiatshunoslik degan ma’noni anglatadi. Fizika fanini birincbi b oiib qadimgi yunon mutafakkiri Aristotel (e.a. 384-322y.) o‘zining 8 toralik kitobida bayon etgan. Texnika va tabiatdagi yangi-yangi hodisalarning kashf qilinishi va ularning amalda qo‘llanilishi natijasida fizikadan fizik-ximiya, astrofizika, geoftzika, biofizika va boshqa mustaqil fanlar ajralib chiqdi."
