        "page": 143,
        "text": "1.5. M EXANIK TEBRANISHLAR VA TO ‘LQINLAR. Tebranma harakat tabiatda eng ko‘p tarqalgan harakatdir. Daraxtlaming shoxi yoki dalalardagi maysalarning tebranib turganini ko‘p kuzatganmiz. Dutor, rubob, childirma kabi musiqa asboblarining torlari, osma soat tebrangichi, ichki yonuv dvigateli slindridagi porshenlaming harakati tebranma harkatdir. Motor ishlab turganda mashina va dastgohlaming korpuslari titrab tebranma harakat qiladi. Telefonda gaplashganda, radiodan ovoz chiqqanda, ulardagi yupqa parda membrana tebranma harakat qiladi. Tabiatdagi har qanday modda molekulalari orasida o'zaro ta’sir mavjuddir."
