    "pages": "153–157-betlar",
    "paragraphs": [
      {
        "page": 153,
        "text": "Ma = pt Syg; -> p.SH a = -p ,S y g , -> a= -& -£- y; -> y= —— ~ - у = -<огу ■ P jH pj H Demak, koordinatadan vaqt bo'yicha olingan 2-tartibli hosila yana korrdinataga bog‘liq boiyapti. Xuddi, avval tanishgan prujinali mayatnik, matematik mayatnik va fizik mayatniklar kabi naydagi suyuqlik sathining harakat tenglamasi у = y m cos cot yoki у = y m sin® г bo'yicha sodir bo'lar ekan. Bu erda: Ia_, JL _ suyuqlik sathi 11Л H tebranishining siklik chastota bo'lib, tebranish chastotasi v=_£L=_L ga, tebranish davri esa 2x 2xllpj H T = ~=2x p L — ga teng bo'ladi. v \\P, g Yeming ichki qismidagi jismning tebranishi: Yeming sirtidan markazigacha quduq kovlangan bo'lsin."
      },
      {
        "page": 154,
        "text": "Toiqinlar tebranishi va tarqalishi yo'nalishlarining o'zaro munosobatiga qarab ikki turga boiinadi: bo'ylama va ko'ndalang to'lqinlar. Agar muhit zarrachalarining tebranish yo'nalishi to'lqin tarqalish yo'nalishiga perpendikulyar bo'lsa, bunday to'lqin ko'ndalang to Iqin deyiladi. Agar muhit zarrachalarining tebranish yo'nalishi to'lqin tarqalish yo'nalishiga parallel bo'lsa, bunday to'lqin bo'ylama to'lqin deyiladi. 1.5.6.1-rasm Ko'ndalang to'lqinlaming hosil bo'lishini elastik shnur yordamida kuzatish mumkin (I.5.5.1a-rasm)."
      },
      {
        "page": 155,
        "text": "a) I b) 1.5.6.2-rasm Toiqinning eng oldingi, ya’ni to‘lqin manbaidan eng uzoqda joylashgan sirti to'lqin fronti deyiladi. Boshqacha aytganda to‘lqin g‘alayoni etib kelgan va endigini muhit zarachalar tebranishi boshlanayotgan sirt to'lqin fronti deyiladi. Demak, to‘lqin fronti to‘lqin egallagan va to‘lqin mavjud boimagan muhit qismini ajratib turuvchi sirtdan iborat ekan. Barcha yo‘nalishlar bo'yicha bir xil xususiyatlarga ega bo‘lgan muhitda, ya’ni izotrop muhitda to‘lqinning fronti O‘zgarmas tezlik bilan siljiydi."
      },
      {
        "page": 156,
        "text": "keltiruvchi manbalar o'zaro kogerent manbalar deyiladi. Masalan, o'zaro kogerent manbani bir xil balandlikdan ikkita bir xil toshni suvga tashalash orqali hosil qilish mumkin. O‘zaro kogerent manbalardan kelayotgan to‘lqinlar fazoning biror nuqtasida qo'shilish natijasida to‘lqin kuchayishi (mavjlanish, g‘alayonlanish) yoki to‘lqin susayishi (sokinlanish) kuzatilishi mumkin. Bunday hodisaga to'lqin interferensiyasi deyiladi. Agar to‘lqinlar bir xil fazada qo'shilsa, to‘lqinlar bir-birini kuchaytiradi (mavjlanadi) va bunda maksimumlar sharti kuzatiladi."
      },
      {
        "page": 157,
        "text": "va to ia mavjlanish oralig'ida bo‘ladi, ya’ni tebranish ampiitudasi \\A, - A2\\< A < A, +A2 oraliqda bo‘ladi.Agar to‘lqinlar o'zaro kogerent boimasachi, bunda interferension manzara qanday ko'rinishda bo'ladi degan savol tug'ilishi ham tabiiy. Bunda tebranishlar fazalari orasidagi farq vaqt o'tishi bilan o'zgarib turgani bois, kuzatilayotgan nuqtadagi interferension manzara ham vaqt o'tishi bilan o'zgarib turadi. Kuzatilayotgan nuqtada goh maksimumlik sharti, goh oraliq qiymatlar va goh minimumlik sharti kuzatilib turadi. To ‘Iqinlar tlifraksiyasi: To'lqin o'z yo'lida katta yoki kichik to'siq va tirqishlarga duch keladi."
      }
    ],
