        "text": "° v ~ 2 M g'imlari quyidragicha bo‘ladi: 5 R 3 R Cp‘ 2 M °v' 2 M 7 R °P1 ~ 2 M 5 R Cl/2 ~ 2 M il I! c’= cM formulaga ko'ra molyar issiqlik sig'imlari quyidagi ko'rmishlarni oladi. - L r . 2 c'p = — R . P 2 Molyar issiqlik sig'imining qiymati modda turiga bog‘liq boimasdan, erkinlik darajasiga bog‘liq bo‘ladi. Izojarayonlarda gazlar aralaslimasining solishtirma issiqlik sig'imlari: Bizga reaksiyaga kirishmaydigan bir necha gazlar aralashmasi berilgan bo‘lib, bu aralashmaning turli izojarayonlardagi solishnirma issiqlik sig'imlari so'ralgan boisin. Bu aralashmadagi gazlaming erkinlik darajalari va modda miqdorlari У1,У2,У3,...У„ boisin."
